BEGIN;
CREATE TABLE employees(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),user_id uuid REFERENCES users(id),employee_number text NOT NULL,legal_name_ciphertext bytea,preferred_name text,job_title text,manager_id uuid REFERENCES employees(id),employment_status text NOT NULL DEFAULT 'onboarding',classification text,work_state text,start_date date,introductory_review_date date,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,employee_number));
CREATE TABLE compensation_plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),employee_id uuid NOT NULL REFERENCES employees(id),basis text NOT NULL,base_rate numeric(12,2),commission_employee_percent numeric(5,2),commission_firm_percent numeric(5,2),effective_from date NOT NULL,effective_to date,approved_by uuid REFERENCES users(id),terms jsonb NOT NULL DEFAULT '{}',CHECK(commission_employee_percent IS NULL OR commission_employee_percent BETWEEN 0 AND 100),CHECK(commission_firm_percent IS NULL OR commission_firm_percent BETWEEN 0 AND 100));
CREATE TABLE time_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),employee_id uuid NOT NULL REFERENCES employees(id),work_date date NOT NULL,hours numeric(5,2) NOT NULL CHECK(hours>=0 AND hours<=24),case_id uuid REFERENCES cases(id),activity_code text NOT NULL,approved_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),client_id uuid NOT NULL REFERENCES clients(id),case_id uuid REFERENCES cases(id),invoice_number text NOT NULL,currency char(3) NOT NULL DEFAULT 'USD',subtotal numeric(14,2) NOT NULL,tax numeric(14,2) NOT NULL DEFAULT 0,total numeric(14,2) GENERATED ALWAYS AS(subtotal+tax) STORED,status text NOT NULL DEFAULT 'draft',due_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,invoice_number));
CREATE TABLE payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),invoice_id uuid REFERENCES invoices(id),provider text NOT NULL,external_reference text,amount numeric(14,2) NOT NULL,currency char(3) NOT NULL DEFAULT 'USD',status text NOT NULL,received_at timestamptz,UNIQUE(tenant_id,provider,external_reference));
CREATE TABLE courses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),code text NOT NULL,title text NOT NULL,version text NOT NULL,status text NOT NULL DEFAULT 'draft',estimated_minutes integer NOT NULL,UNIQUE(tenant_id,code,version));
CREATE TABLE course_modules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),course_id uuid NOT NULL REFERENCES courses(id) ON DELETE CASCADE,sequence_no integer NOT NULL,title text NOT NULL,content_object_key text,assessment_required boolean NOT NULL DEFAULT false,UNIQUE(course_id,sequence_no));
CREATE TABLE enrollments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),course_id uuid NOT NULL REFERENCES courses(id),user_id uuid NOT NULL REFERENCES users(id),status text NOT NULL DEFAULT 'assigned',assigned_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,score numeric(5,2),UNIQUE(course_id,user_id));
CREATE TABLE credentials(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),user_id uuid NOT NULL REFERENCES users(id),kind text NOT NULL,identifier_ciphertext bytea,issuer text,issued_at date,expires_at date,status evidence_status NOT NULL DEFAULT 'provided');
CREATE TABLE policy_acknowledgments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),user_id uuid NOT NULL REFERENCES users(id),policy_code text NOT NULL,policy_version text NOT NULL,acknowledged_at timestamptz NOT NULL,ip_hash text,UNIQUE(user_id,policy_code,policy_version));
ALTER TABLE employees ENABLE ROW LEVEL SECURITY;ALTER TABLE compensation_plans ENABLE ROW LEVEL SECURITY;ALTER TABLE time_entries ENABLE ROW LEVEL SECURITY;ALTER TABLE invoices ENABLE ROW LEVEL SECURITY;ALTER TABLE payments ENABLE ROW LEVEL SECURITY;ALTER TABLE enrollments ENABLE ROW LEVEL SECURITY;
COMMIT;
